std::uint32_t stringHash(std::string_view value){
    std::array<std::uint8_t,1023> bytes{};size_t n=0;for(unsigned char ch:value){if(!ch || n==bytes.size())break;if(ch>='a' && ch<='z')ch-=32;else if(ch=='/')ch='\\';bytes[n++]=ch;}if(!n)return 0;
    std::uint32_t a=0x9e3779b9u,b=a,c=0;auto mix=[&]{a-=b;a-=c;a^=c>>13;b-=c;b-=a;b^=a<<8;c-=a;c-=b;c^=b>>13;a-=b;a-=c;a^=c>>12;b-=c;b-=a;b^=a<<16;c-=a;c-=b;c^=b>>5;a-=b;a-=c;a^=c>>3;b-=c;b-=a;b^=a<<10;c-=a;c-=b;c^=b>>15;};
    auto word=[&](size_t at){return std::uint32_t(bytes[at])|(std::uint32_t(bytes[at+1])<<8)|(std::uint32_t(bytes[at+2])<<16)|(std::uint32_t(bytes[at+3])<<24);};size_t i=0;for(;n-i>=12;i+=12){a+=word(i);b+=word(i+4);c+=word(i+8);mix();}c+=std::uint32_t(n);for(size_t j=0;j<n-i;++j){auto v=std::uint32_t(bytes[i+j]);if(j<4)a+=v<<(8*j);else if(j<8)b+=v<<(8*(j-4));else c+=v<<(8*(j-7));}mix();return c;
}
