Bytes ScriptSession::encodePresentation() const {
    constexpr size_t budget=20u*1024u*1024u;if(!runtime_.snapshotSafe() || failed_ || !world_ || !setupApplied_ || !contexts_.empty() || experimentalSelectionSync_ || !networkPlayers_.empty())throw std::runtime_error("Presentation snapshot requires a quiescent local session");SnapshotWriter out(budget-64);out.u32(tag("SPRS"));out.u32(1);out.text(world_->resources().mapDigest(),64);auto number=[&](double value){if(!std::isfinite(value))throw std::runtime_error("Invalid presentation time");out.u64(std::bit_cast<std::uint64_t>(value));};auto real=[&](float value){if(!std::isfinite(value))throw std::runtime_error("Invalid presentation value");out.u32(std::bit_cast<std::uint32_t>(value));};number(simulationTime_);auto& env=world_->environment();std::uint32_t flags=0;unsigned bit=0;for(bool value:{userControl_,userUI_,selectionEnabled_,selectionUI_,dragSelectionEnabled_,dragSelectionUI_,occlusionEnabled_,forceCinematicSubtitles_,interfaceVisible_,env.preSelectionEnabled,env.preSelectionUI,env.creepCampFilter,env.allyFilterButtonEnabled,env.creepFilterButtonEnabled}){if(value)flags|=1u<<bit;++bit;}out.u32(flags);out.u32(std::bit_cast<std::uint32_t>(reservedLocalHeroButtons_));out.u32(std::bit_cast<std::uint32_t>(env.allyColorFilter));out.text(env.skyModel,65536);real(interfaceFrom_);number(interfaceChanged_);number(interfaceDuration_);auto& filter=cineFilter_;out.text(filter.texture,1024);out.u32(filter.blend);out.u32(filter.flags);for(auto value:filter.startUV)real(value);for(auto value:filter.endUV)real(value);for(auto value:filter.startColor)out.u32(value);for(auto value:filter.endColor)out.u32(value);number(filter.duration);number(filter.started);out.u32(filter.displayed?1:0);out.u32(cinematicScene_?1:0);if(cinematicScene_){auto& scene=*cinematicScene_;out.u32(scene.portrait);out.u32(scene.color);out.text(scene.model,65536);out.text(scene.speaker,65536);out.text(scene.dialogue,65536);number(scene.started);number(scene.expires);number(scene.voiceUntil);}auto messages=[&](const std::vector<ScriptText>& values){if(values.size()>128)throw std::runtime_error("Presentation text count exceeds budget");out.size(values.size());for(auto& value:values){if(value.owner>16)throw std::runtime_error("Invalid presentation text owner");out.u32(value.owner);real(value.x);real(value.y);number(value.expires);out.text(value.text,65536);out.u32(value.audience);out.u32(value.chat?1:0);}};messages(texts_);messages(textHistory_);if(minimapPings_.size()>16)throw std::runtime_error("Presentation ping count exceeds budget");out.u64(nextMinimapPing_);out.size(minimapPings_.size());for(auto& ping:minimapPings_){if(!ping.id || ping.id>nextMinimapPing_)throw std::runtime_error("Invalid presentation ping");out.u64(ping.id);real(ping.x);real(ping.y);number(ping.started);number(ping.expires);out.u32(ping.color);out.u32(ping.extra?1:0);}number(nextAttackAlert_);number(nextAllyAttackAlert_);return sealSnapshot(out.finish(),budget);
}
void ScriptSession::restorePresentation(std::span<const std::uint8_t> bytes) {
    constexpr size_t budget=20u*1024u*1024u;if(!runtime_.ready() || failed_ || !world_ || !setupApplied_ || mainAttempted_ || presentationRestored_ || runtime_.threadCount() || !runtime_.inspectExecutions().empty() || !contexts_.empty() || experimentalSelectionSync_ || !networkPlayers_.empty())throw std::runtime_error("Presentation restore requires a fresh quiescent session");Binary in(openSnapshot(bytes,budget));in.expect(tag("SPRS"));if(in.u32()!=1 || snapshotText(in,64)!=world_->resources().mapDigest())throw std::runtime_error("Presentation snapshot map or version differs");auto number=[&]{auto value=std::bit_cast<double>(snapshotU64(in));if(!std::isfinite(value))throw std::runtime_error("Invalid presentation time");return value;};auto real=[&]{auto value=std::bit_cast<float>(in.u32());if(!std::isfinite(value))throw std::runtime_error("Invalid presentation value");return value;};auto flag=[&]{auto value=in.u32();if(value>1)throw std::runtime_error("Invalid presentation flag");return value!=0;};if(number()!=simulationTime_)throw std::runtime_error("Presentation snapshot clock differs");auto flags=in.u32();if(flags>>14)throw std::runtime_error("Invalid presentation flags");auto reserved=std::bit_cast<std::int32_t>(in.u32()),ally=std::bit_cast<std::int32_t>(in.u32());auto sky=snapshotText(in,65536);auto from=real();auto changed=number(),duration=number();if(from<0 || from>1 || changed<0 || duration<0)throw std::runtime_error("Invalid interface transition");ScriptCineFilter filter;filter.texture=snapshotText(in,1024);filter.blend=in.u32();filter.flags=in.u32();if(filter.blend>5 || filter.flags>3)throw std::runtime_error("Invalid cinematic filter");for(auto& value:filter.startUV)value=real();for(auto& value:filter.endUV)value=real();for(auto* colors:{&filter.startColor,&filter.endColor})for(auto& value:*colors){value=in.u32();if(value>255)throw std::runtime_error("Invalid cinematic filter color");}filter.duration=number();filter.started=number();filter.displayed=flag();if(filter.duration<0 || filter.started<0)throw std::runtime_error("Invalid cinematic filter time");std::optional<ScriptCinematicScene> scene;if(flag()){scene.emplace();scene->portrait=in.u32();scene->color=in.u32();scene->model=snapshotText(in,65536);scene->speaker=snapshotText(in,65536);scene->dialogue=snapshotText(in,65536);scene->started=number();scene->expires=number();scene->voiceUntil=number();if(scene->started<0 || scene->expires<scene->started || scene->voiceUntil<scene->started)throw std::runtime_error("Invalid cinematic scene time");}auto messages=[&]{std::vector<ScriptText> values;auto count=in.count(28,128);values.reserve(count);for(unsigned i=0;i<count;++i){ScriptText value;value.owner=in.u32();value.x=real();value.y=real();value.expires=number();value.text=snapshotText(in,65536);auto audience=in.u32();value.chat=flag();if(value.owner>16 || audience>0xffff || value.expires<0)throw std::runtime_error("Invalid presentation text");value.audience=std::uint16_t(audience);values.push_back(std::move(value));}return values;};auto texts=messages(),history=messages();size_t historyBytes=0;for(auto& entry:history)historyBytes+=entry.text.size();if(historyBytes>256u*1024u)throw std::runtime_error("Presentation history exceeds budget");auto nextPing=snapshotU64(in);std::vector<ScriptMinimapPing> pings;auto count=in.count(40,16);std::set<std::uint64_t> pingIds;for(unsigned i=0;i<count;++i){ScriptMinimapPing ping;ping.id=snapshotU64(in);ping.x=real();ping.y=real();ping.started=number();ping.expires=number();ping.color=in.u32();ping.extra=flag();if(!ping.id || ping.id>nextPing || !pingIds.insert(ping.id).second || ping.started<0 || ping.expires<ping.started)throw std::runtime_error("Invalid presentation ping");pings.push_back(ping);}auto nextAlert=number(),nextAlly=number();if(nextAlert<0 || nextAlly<0)throw std::runtime_error("Invalid attack alert time");in.finish();unsigned bit=0;auto value=[&]{return (flags&(1u<<bit++))!=0;};userControl_=value();userUI_=value();selectionEnabled_=value();selectionUI_=value();dragSelectionEnabled_=value();dragSelectionUI_=value();occlusionEnabled_=value();forceCinematicSubtitles_=value();interfaceVisible_=value();auto& env=world_->environment();env.preSelectionEnabled=value();env.preSelectionUI=value();env.creepCampFilter=value();env.allyFilterButtonEnabled=value();env.creepFilterButtonEnabled=value();reservedLocalHeroButtons_=reserved;env.allyColorFilter=ally;env.skyModel=std::move(sky);interfaceFrom_=from;interfaceChanged_=changed;interfaceDuration_=duration;cineFilter_=std::move(filter);cinematicScene_=std::move(scene);texts_.swap(texts);textHistory_.swap(history);textHistoryBytes_=historyBytes;minimapPings_.swap(pings);nextMinimapPing_=nextPing;nextAttackAlert_=nextAlert;nextAllyAttackAlert_=nextAlly;presentationRestored_=true;
}
Bytes ScriptSession::encodeUIRequests(const jass::StableHandleMap& encodeHandle) const {
    constexpr size_t budget=16384;if(!runtime_.snapshotSafe() || failed_ || !world_ || !setupApplied_ || !contexts_.empty() || experimentalSelectionSync_ || !networkPlayers_.empty() || forcedUIKeys_.size()>1024)throw std::runtime_error("UI request snapshot requires a quiescent local session");SnapshotWriter out(budget-64);out.u32(tag("SUIQ"));out.u32(2);out.text(world_->resources().mapDigest(),64);out.u64(std::bit_cast<std::uint64_t>(simulationTime_));out.size(forcedUIKeys_.size());for(auto key:forcedUIKeys_){if(!((key>='A' && key<='Z') || (key>='0' && key<='9') || key==512 || key==513))throw std::runtime_error("Invalid forced UI key");out.u32(key);}out.u32(requestedBook_?1:0);if(requestedBook_){auto [unit,ability]=*requestedBook_;if(!unit || !ability || !encodeHandle || unit<handleBase || unit-handleBase>=objects_.size() || objects_[unit-handleBase].kind!=NativeKind::Unit)throw std::runtime_error("Invalid spell book request");auto saved=encodeHandle("unit",unit);if(!saved)throw std::runtime_error("Invalid spell book mapping");out.u32(saved);out.u32(objects_[unit-handleBase].alive?1:0);out.u32(ability);}return sealSnapshot(out.finish(),budget);
}
void ScriptSession::restoreUIRequests(std::span<const std::uint8_t> bytes,const jass::StableHandleMap& decodeHandle) {
    constexpr size_t budget=16384;if(!runtime_.ready() || failed_ || !world_ || !setupApplied_ || mainAttempted_ || !unitRecoveryIncomplete_ || !unitCoreFinished_ || uiRequestsRestored_ || runtime_.threadCount() || !runtime_.inspectExecutions().empty() || !contexts_.empty() || experimentalSelectionSync_ || !networkPlayers_.empty() || liveObjects(NativeKind::Event))throw std::runtime_error("UI request restore requires rebuilt units before events");Binary in(openSnapshot(bytes,budget));in.expect(tag("SUIQ"));auto version=in.u32();if((version!=1 && version!=2) || snapshotText(in,64)!=world_->resources().mapDigest() || snapshotU64(in)!=std::bit_cast<std::uint64_t>(simulationTime_))throw std::runtime_error("UI request map or clock differs");auto n=in.count(4,1024);std::deque<unsigned> keys;for(unsigned i=0;i<n;++i){auto key=in.u32();if(!((key>='A' && key<='Z') || (key>='0' && key<='9') || key==512 || (key==513 && version>=2)))throw std::runtime_error("Invalid forced UI key");keys.push_back(key);}auto hasBook=in.u32();if(hasBook>1)throw std::runtime_error("Invalid spell book flag");std::optional<std::pair<std::uint32_t,std::uint32_t>> book;if(hasBook){auto saved=in.u32(),live=in.u32(),ability=in.u32(),unit=decodeHandle?decodeHandle("unit",saved):0;if(!saved || live>1 || !ability || !unit || !unitIdentityHandles_.contains(saved) || unitIdentityHandles_.at(saved)!=unit || unit<handleBase || unit-handleBase>=objects_.size() || objects_[unit-handleBase].kind!=NativeKind::Unit || objects_[unit-handleBase].alive!=(live!=0))throw std::runtime_error("Invalid spell book mapping");book=std::pair{unit,ability};}in.finish();forcedUIKeys_.swap(keys);requestedBook_=book;uiRequestsRestored_=true;
}
void ScriptSession::displayText(unsigned owner,float x,float y,double duration,std::string message,std::uint16_t audience,bool chat) {if(owner>16 || !std::isfinite(x) || !std::isfinite(y) || !std::isfinite(duration) || duration<0 || message.size()>65536)throw std::runtime_error("Invalid script text message");std::erase_if(texts_,[&](auto& t){return t.expires<=simulationTime_;});if(texts_.size()>=128)texts_.erase(texts_.begin());texts_.push_back({owner,x,y,simulationTime_+duration,std::move(message),audience,chat});if(localPlayer_ && (owner==*localPlayer_ || (owner==16 && (audience&(1u<<*localPlayer_))))){auto& entry=texts_.back();constexpr size_t bytes=256*1024;while(!textHistory_.empty() && (textHistory_.size()>=128 || textHistoryBytes_+entry.text.size()>bytes)){textHistoryBytes_-=textHistory_.front().text.size();textHistory_.erase(textHistory_.begin());}textHistoryBytes_+=entry.text.size();textHistory_.push_back(entry);}}
void ScriptSession::attackAlert(const UnitState& unit) {
    if(!localPlayer_ || *localPlayer_>=16 || unit.owner>=16 || unit.ignoreAlarm)return;bool ally=unit.owner!=*localPlayer_;if(ally && !(config_.players[*localPlayer_].alliances[unit.owner]&1u))return;auto& next=ally?nextAllyAttackAlert_:nextAttackAlert_;if(simulationTime_<next)return;auto race=config_.players[*localPlayer_].displayRace();if(!attackAlertLabels_ || attackAlertRace_!=race){SourceSettings skins;skins.load(requireWorld().resources(),"UI\\war3skins.txt");if(auto overlay=requireWorld().resources().readCandidates({"war3mapSkin.txt"},ArchiveScope::Map))skins.parse(overlay->bytes);auto section=race==2?"Orc":race==3?"Undead":race==4?"NightElf":"Human";auto label=[&](const char* key){return skins.value(section,key,skins.value("Default",key));};attackAlertLabels_=std::array<std::string,4>{label("UnderAttackSound"),label("TownAttackSound"),label("AllyUnderAttackSound"),label("AllyTownUnderAttackSound")};attackAlertRace_=race;}next=simulationTime_+8;minimapPing(std::bit_cast<float>(unit.x.bits()),std::bit_cast<float>(unit.y.bits()),3,pingColors().second,false);queueLabelSound((*attackAlertLabels_)[(ally?2:0)+(unit.building?1:0)],{unit.x,unit.y});
}
bool ScriptSession::playerMinimapSignal(unsigned sender,WorldPoint point){if(sender>=16 || !std::isfinite(std::bit_cast<float>(point.x.bits())) || !std::isfinite(std::bit_cast<float>(point.y.bits())))return false;if(!localPlayer_ || *localPlayer_>=16 || (sender!=*localPlayer_ && !(config_.players[sender].alliances[*localPlayer_]&1u)))return true;point=requireWorld().clamp(point);minimapPing(std::bit_cast<float>(point.x.bits()),std::bit_cast<float>(point.y.bits()),0,std::nullopt,true);return true;}
std::pair<std::uint32_t,std::uint32_t> ScriptSession::pingColors(){if(!minimapPingColors_){SourceSettings settings;settings.load(requireWorld().resources(),"UI\\MiscData.txt");if(auto overlay=requireWorld().resources().readCandidates({"war3mapMisc.txt"},ArchiveScope::Map))settings.parse(overlay->bytes);auto parse=[](const std::string& source){std::istringstream stream(source);std::array<unsigned,4> color{};for(unsigned i=0;i<4;++i){int value=-1;stream>>value;if(!stream || value<0 || value>255)throw std::runtime_error("Invalid minimap ping color");color[i]=unsigned(value);if(i<3){char comma=0;stream>>comma;if(comma!=',')throw std::runtime_error("Invalid minimap ping color");}}stream>>std::ws;if(!stream.eof())throw std::runtime_error("Invalid minimap ping color");return (color[0]<<24)|(color[1]<<16)|(color[2]<<8)|color[3];};minimapPingColors_=std::pair{parse(settings.value("PingColor","PingColor","255,0,255,0")),parse(settings.value("PingColor","PingAttackColor","255,255,0,0"))};}return *minimapPingColors_;}
void ScriptSession::minimapPing(float x,float y,float duration,std::optional<std::uint32_t> requested,bool extra){if(!std::isfinite(x) || !std::isfinite(y) || !std::isfinite(duration))throw std::runtime_error("Invalid minimap ping");auto [normal,attack]=pingColors();auto color=requested.value_or(normal);if(duration<=0)duration=color==attack?3.f:1.5f;std::erase_if(minimapPings_,[&](const auto& item){return item.expires<=simulationTime_;});if(minimapPings_.size()>=16)return;extra=extra && color!=attack;if(extra){auto voice=requireAudio().fromLabel("MapPing",false,false,false,0,0);requireAudio().start(voice);requireAudio().releaseWhenDone(voice);}minimapPings_.push_back({++nextMinimapPing_,x,y,simulationTime_,simulationTime_+double(duration),color,extra});}
void ScriptSession::bindTextNatives() {
    bind("SetCreepCampFilterState","nothing",{"boolean"},[this](auto& vm,auto a){requireWorld().environment().creepCampFilter=a[0].bits!=0;return vm.nothing();});
    bind("GetCreepCampFilterState","boolean",{},[this](auto& vm,auto){return vm.boolean(requireWorld().environment().creepCampFilter);});
    bind("EnableMinimapFilterButtons","nothing",{"boolean","boolean"},[this](auto& vm,auto a){auto& env=requireWorld().environment();env.allyFilterButtonEnabled=a[0].bits!=0;env.creepFilterButtonEnabled=a[1].bits!=0;return vm.nothing();});
    bind("SetAllyColorFilterState","nothing",{"integer"},[this](auto& vm,auto a){requireWorld().environment().allyColorFilter=std::bit_cast<std::int32_t>(a[0].bits);return vm.nothing();});
    bind("GetAllyColorFilterState","integer",{},[this](auto& vm,auto){return vm.integer(requireWorld().environment().allyColorFilter);});
    auto text=[](jass::Value v){return v.text?*v.text:std::string{};};
    bind("PingMinimap","nothing",{"real","real","real"},[this](auto& vm,auto a){minimapPing(std::bit_cast<float>(a[0].bits),std::bit_cast<float>(a[1].bits),std::bit_cast<float>(a[2].bits),std::nullopt,false);return vm.nothing();});
    bind("PingMinimapEx","nothing",{"real","real","real","integer","integer","integer","boolean"},[this](auto& vm,auto a){auto color=0xff000000u|((a[3].bits&255u)<<16)|((a[4].bits&255u)<<8)|(a[5].bits&255u);minimapPing(std::bit_cast<float>(a[0].bits),std::bit_cast<float>(a[1].bits),std::bit_cast<float>(a[2].bits),color,a[6].bits!=0);return vm.nothing();});
    bind("ShowInterface","nothing",{"boolean","real"},[this](auto& vm,auto a){auto duration=std::bit_cast<float>(a[1].bits);if(!std::isfinite(duration))throw std::runtime_error("Invalid interface transition duration");interfaceFrom_=interfaceAmount();interfaceVisible_=a[0].bits!=0;interfaceChanged_=simulationTime_;interfaceDuration_=std::max(0.f,duration);return vm.nothing();});
    bind("SetCinematicScene","nothing",{"integer","playercolor","string","string","real","real"},[this,text](auto& vm,auto a){auto duration=std::bit_cast<float>(a[4].bits),voice=std::bit_cast<float>(a[5].bits);if(!std::isfinite(duration) || !std::isfinite(voice))throw std::runtime_error("Invalid cinematic scene duration");ScriptCinematicScene scene;scene.portrait=a[0].bits;scene.color=a[1].bits;scene.speaker=mapString(text(a[2]),strings_);scene.dialogue=mapString(text(a[3]),strings_);if(scene.speaker.size()>65536 || scene.dialogue.size()>65536)throw std::runtime_error("Cinematic scene text exceeds budget");scene.started=simulationTime_;scene.expires=simulationTime_+std::max(0.f,duration);scene.voiceUntil=simulationTime_+std::max(0.f,voice);if(scene.portrait && definitions().contains(scene.portrait)){auto source=definitions().field(scene.portrait,"UnitUI","file");if(!source.empty() && source!="_"){auto extension=fs::path(wide(source)).extension().wstring();if(extension==L".mdl" || extension==L".MDL" || extension==L".mdx" || extension==L".MDX")source.resize(source.size()-4);auto portrait=source+"_Portrait.mdx";scene.model=requireWorld().resources().readCandidates({portrait})?portrait:source+".mdx";}}cinematicScene_=std::move(scene);return vm.nothing();});
    bind("EndCinematicScene","nothing",{},[this](auto& vm,auto){cinematicScene_.reset();return vm.nothing();});
    bind("I2S","string",{"integer"},[](auto& vm,auto a){return vm.string(std::to_string(std::bit_cast<std::int32_t>(a[0].bits)));});
    bind("R2S","string",{"real"},[](auto& vm,auto a){auto value=std::bit_cast<float>(a[0].bits);if(!std::isfinite(value))throw std::runtime_error("Non-finite real string conversion");char buffer[128];std::snprintf(buffer,sizeof(buffer),"%.3f",value);return vm.string(buffer);});
    bind("R2SW","string",{"real","integer","integer"},[](auto& vm,auto a){auto value=std::bit_cast<float>(a[0].bits);if(!std::isfinite(value))throw std::runtime_error("Non-finite formatted real");int width=std::clamp(std::bit_cast<std::int32_t>(a[1].bits),-64,64),precision=std::clamp(std::bit_cast<std::int32_t>(a[2].bits),0,32);char buffer[256];std::snprintf(buffer,sizeof(buffer),"%*.*f",width,precision,value);return vm.string(buffer);});
    bind("S2I","integer",{"string"},[text](auto& vm,auto a){auto value=text(a[0]);return vm.integer(std::int32_t(std::strtol(value.c_str(),nullptr,10)));});
    bind("S2R","real",{"string"},[text](auto& vm,auto a){auto value=text(a[0]);auto result=std::strtof(value.c_str(),nullptr);if(!std::isfinite(result))throw std::runtime_error("Non-finite string real conversion");return vm.real(jass::Real::fromBits(std::bit_cast<std::uint32_t>(result)));});
    bind("StringHash","integer",{"string"},[](auto& vm,auto a){return vm.integer(std::bit_cast<std::int32_t>(a[0].text?stringHash(*a[0].text):0u));});
    bind("StringLength","integer",{"string"},[text](auto& vm,auto a){return vm.integer(int(text(a[0]).size()));});
    bind("SubString","string",{"string","integer","integer"},[text](auto& vm,auto a){auto value=text(a[0]);auto start=std::clamp(std::bit_cast<std::int32_t>(a[1].bits),0,int(value.size())),end=std::clamp(std::bit_cast<std::int32_t>(a[2].bits),start,int(value.size()));return vm.string(value.substr(start,end-start));});
    bind("StringCase","string",{"string","boolean"},[text](auto& vm,auto a){auto value=text(a[0]);for(auto& c:value)if(static_cast<unsigned char>(c)<128)c=char(a[1].bits?std::toupper(static_cast<unsigned char>(c)):std::tolower(static_cast<unsigned char>(c)));return vm.string(std::move(value));});
    bind("DisplayTextToPlayer","nothing",{"player","real","real","string"},[this,text](auto& vm,auto a){displayText(playerId(a[0]),std::bit_cast<float>(a[1].bits),std::bit_cast<float>(a[2].bits),10,mapString(text(a[3]),strings_));return vm.nothing();});
    bind("DisplayTimedTextToPlayer","nothing",{"player","real","real","real","string"},[this,text](auto& vm,auto a){displayText(playerId(a[0]),std::bit_cast<float>(a[1].bits),std::bit_cast<float>(a[2].bits),std::bit_cast<float>(a[3].bits),mapString(text(a[4]),strings_));return vm.nothing();});
    bind("DisplayTimedTextFromPlayer","nothing",{"player","real","real","real","string"},[this,text](auto& vm,auto a){auto owner=playerId(a[0]);auto name=config_.players[owner].name;if(name.empty())name=localized("PLAYER")+" "+std::to_string(owner+1);auto format=mapString(text(a[4]),strings_);std::string message;message.reserve(format.size());bool inserted=false;for(size_t i=0;i<format.size();++i){if(format[i]=='%' && i+1<format.size()){if(format[i+1]=='%'){message+='%';++i;continue;}if(format[i+1]=='s' && !inserted){message+=name;inserted=true;++i;continue;}}message+=format[i];}displayText(16,std::bit_cast<float>(a[1].bits),std::bit_cast<float>(a[2].bits),std::bit_cast<float>(a[3].bits),std::move(message),0xffff);return vm.nothing();});
    bind("ClearTextMessages","nothing",{},[this](auto& vm,auto){texts_.clear();return vm.nothing();});
    bind("SetSkyModel","nothing",{"string"},[this,text](auto& vm,auto a){requireWorld().environment().skyModel=text(a[0]);return vm.nothing();});
}
